#!/bin/zsh
# 模型页第二版：下载可续传/换国内源、本机推理程序检测与安装、云端转写、更多云端服务预设。
cd "$(dirname "$0")"
gen() {
  local name=$1; local prompt=$2
  [ -f "$name.png" ] && return
  local t0=$(date +%s)
  codex exec --skip-git-repo-check --ephemeral -c 'model_reasoning_effort="low"' -C "$PWD" -s workspace-write \
    "请使用内置的 image_gen 工具生成一张高保真 UI 设计稿（像设计师在 Figma 里做的最终稿截图，正视图、不要透视、纯浅灰背景上只放这一个窗口）：$prompt 生成后把最终图片复制到当前目录，命名为 $name.png，然后只回复文件名。" < /dev/null > "$name.log" 2>&1
  echo "$name $(( $(date +%s) - t0 ))s $([ -f $name.png ] && echo ok || echo FAIL)"
}
S="这是 macOS 桌面应用「豆仓」（把录音转成文字、整理成纪要）的设置窗口。设计语言：苹果 macOS 最新系统设置的风格加乔纳森·艾维式的克制——分组圆角卡片、行与行之间细分隔线、左边标题右边控件、说明是小号灰字、对齐严谨、留白舒服。配色严格限定：暖灰纸色背景（#FAF9F7）、卡片纯白、深暖灰文字（#1C1917）、唯一强调色玫瑰红（#F43F5E，用在主按钮、开关、选中的分段和选中的页签）、绿色只用于「已就绪」小勾、琥珀色只用于「需要处理」的小提示；绝对不要蓝色、紫色、青色。界面文字全部是简体中文，字体像苹方，清晰可读、没有乱码。"
gen ui_models2 "【设置窗口，「模型」页签选中】窗口宽约 680，顶部一排居中的页签（线条图标+小字）「通用」「语音输入」「模型」「词库」「连接」，「模型」选中为玫瑰红。内容从上到下三张卡片，每张卡片左上是图标+粗体标题，右上是状态胶囊。
第一张「本机运行环境」，状态胶囊琥珀色「需要安装」：一行「推理程序 llama.cpp」右边灰字「没找到」和一个玫瑰红小按钮「安装」；下面小灰字「本机转写和本机整理模型都靠它运行。安装时会用 Homebrew，大约 1 分钟。」。
第二张「转写：把声音变成文字」，状态胶囊绿色小勾「已就绪」：一行「引擎」右边是三段分段选择「本机 Qwen3-ASR」「系统识别」「云端」（第一个选中）；一行「模型」右边灰字「Qwen3-ASR 0.6B · 已下载 · 1.0 GB」；下面小灰字「在这台 Mac 上运行，录音不会上传。」；再一行「云端重转」右边灰字「未设置」和小按钮「设置…」，下面小灰字「本机转得不准的录音，可以在录音页按需交给云端再转一遍。」。
第三张「整理：写纪要、回答提问」，状态胶囊绿色小勾「已就绪」：三段分段「云端优先」「只用云端」「只用本机」（第一个选中），下面分左右两块：左块「本机模型」写「Qwen3-4B · 正在下载 42%」，下面一条玫瑰红细进度条、旁边小灰字「1.0 / 2.5 GB · 国内镜像 · 8.6 MB/s」和两个小按钮「暂停」「取消」；右块「云端服务」写「小米 MiMo · mimo-v2.6-pro」和两个小按钮「更改…」「测试」。底部小灰字「下载断了会从断点接着下；HuggingFace 太慢时自动换国内镜像。」。$S" &
gen ui_cloud_providers "【「选择云端服务」弹出单】宽约 600。标题「云端服务」，下面小灰字「任何兼容 OpenAI 接口的服务都能用。密钥存在系统钥匙串里。」。然后是一个服务网格，4 列 3 行的圆角小卡片，每张卡片只有服务名文字（不要任何真实品牌 Logo，用一个简单的首字母圆形灰色小徽标代替）：「小米 MiMo」（选中，玫瑰红描边和右上角小勾）「DeepSeek」「通义千问」「Kimi」「豆包」「智谱 GLM」「MiniMax」「硅基流动」「OpenRouter」「Gemini」「Claude」「OpenAI」；网格下面一行两个小一点的胶囊「本机 Ollama」「本机 LM Studio」和一个「自定义…」。再下面是表单：「接口地址」输入框灰字填着 https://api.xiaomimimo.com/v1（右侧小字「已自动填好」）；「模型」下拉显示「mimo-v2.6-pro」，旁边小链接「刷新列表」；「密钥」密码框显示圆点，右侧小链接「去获取密钥」。底部左边一行小绿字「测试通过 · 2.1 秒 · 把销售通话判成了「销售」」，右下角按钮「测试一下」和玫瑰红实心「完成」。$S" &
wait
